// The built-in "Xin chào." greeting (src/greeting_mp3.h, generated by tools/embed_asset.py) as an audio job. The MP3 is
// checked with the same header walk as downloaded voice messages before it is queued; it plays through the MP3 decoder.
#pragma once

#include <string.h>

#include "audio.h"
#include "greeting_mp3.h"
#include "mp3.h"

namespace carelens {

inline Mp3Error greetingJob(AudioJob* j) {
  Mp3Info info;
  const Mp3Error e = inspectMp3(kGreetingMp3, kGreetingMp3Len, &info);
  if (e != Mp3Error::kOk) return e;
  *j = AudioJob();
  j->kind = AudioKind::kMp3;
  strcpy(j->tag, "local:greeting");
  j->data = kGreetingMp3;
  j->bytes = kGreetingMp3Len;
  j->mp3 = info;
  j->channels = info.channels;
  j->rate = info.sample_rate;
  return Mp3Error::kOk;
}

}  // namespace carelens
